From 33cb8794028a538574ed83e69e8a2c5ab09b50d0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:46:30 +0100
Subject: [PATCH] Add option to turn off the background blur in Breeze theme

The Breeze login screen always blurred the background behind the login
prompt, with no way to change it. Add a checkbox next to "Show clock"
that writes the theme's new blurBackground key to theme.conf.user.

BUG: 455757
---
 src/sddmkcm.cpp     |  1 +
 src/themesmodel.cpp | 10 ++++++++++
 src/themesmodel.h   |  2 ++
 src/ui/main.qml     | 20 ++++++++++++++++----
 4 files changed, 29 insertions(+), 4 deletions(-)

diff --git a/src/sddmkcm.cpp b/src/sddmkcm.cpp
index 876f0b6..26a0933 100644
--- a/src/sddmkcm.cpp
+++ b/src/sddmkcm.cpp
@@ -131,6 +131,7 @@ void SddmKcm::save()
             args[QStringLiteral("theme.conf.user/General/type")] = QStringLiteral("color");
         }
         args[QStringLiteral("theme.conf.user/General/showClock")] = m_themesModel->data(currentThemeIndex, ThemesModel::ShowClockRole).toBool();
+        args[QStringLiteral("theme.conf.user/General/blurBackground")] = m_themesModel->data(currentThemeIndex, ThemesModel::BlurBackgroundRole).toBool();
     }
     args[QStringLiteral("kde_settings.conf/Theme/Current")] = currentThemeIndex.data(ThemesModel::IdRole);
     args[QStringLiteral("kde_settings.conf/Autologin/User")] = m_data->sddmSettings()->user();
diff --git a/src/themesmodel.cpp b/src/themesmodel.cpp
index 9c9c156..afcc852 100644
--- a/src/themesmodel.cpp
+++ b/src/themesmodel.cpp
@@ -56,6 +56,7 @@ QHash<int, QByteArray> ThemesModel::roleNames() const
         {BackgroundDirtyRole, QByteArrayLiteral("backgroundDirty")},
         {DeletableRole, QByteArrayLiteral("deletable")},
         {ShowClockRole, QByteArrayLiteral("showClock")},
+        {BlurBackgroundRole, QByteArrayLiteral("blurBackground")},
     };
 }

@@ -109,6 +110,8 @@ QVariant ThemesModel::data(const QModelIndex &index, int role) const
         break;
     case ThemesModel::ShowClockRole:
         return m_showClock[metadata.themeid()];
+    case ThemesModel::BlurBackgroundRole:
+        return m_blurBackground[metadata.themeid()];
     }

     return QVariant();
@@ -136,6 +139,11 @@ bool ThemesModel::setData(const QModelIndex &index, const QVariant &value, int r
         Q_EMIT dataChanged(index, index, {ThemesModel::ShowClockRole});
         return true;
     }
+    if (role == ThemesModel::BlurBackgroundRole) {
+        m_blurBackground[mThemeList[index.row()].themeid()] = value.toBool();
+        Q_EMIT dataChanged(index, index, {ThemesModel::BlurBackgroundRole});
+        return true;
+    }
     return false;
 }

@@ -206,6 +214,8 @@ void ThemesModel::add(const QString &id, const QString &path)
         m_wallpaperDirty.insert(data.themeid(), false);
         const bool showClock = themeConfig->group(QStringLiteral("General")).readEntry("showClock", true);
         m_showClock.insert(data.themeid(), showClock);
+        const bool blurBackground = themeConfig->group(QStringLiteral("General")).readEntry("blurBackground", true);
+        m_blurBackground.insert(data.themeid(), blurBackground);
     }
     endInsertRows();
 }
diff --git a/src/themesmodel.h b/src/themesmodel.h
index 7c7cedc..fe183c5 100644
--- a/src/themesmodel.h
+++ b/src/themesmodel.h
@@ -34,6 +34,7 @@ public:
         BackgroundDirtyRole,
         DeletableRole,
         ShowClockRole,
+        BlurBackgroundRole,
     };
     Q_ENUM(Roles)

@@ -63,6 +64,7 @@ private:
     QHash<QString, QString> m_currentWallpapers;
     QHash<QString, bool> m_wallpaperDirty;
     QHash<QString, bool> m_showClock;
+    QHash<QString, bool> m_blurBackground;
     QList<QString> m_customInstalledThemes;
 };

diff --git a/src/ui/main.qml b/src/ui/main.qml
index 3bf0a88..4e08656 100644
--- a/src/ui/main.qml
+++ b/src/ui/main.qml
@@ -105,6 +105,7 @@ KCM.GridViewKCM {
                     const index = view.model.index(view.currentIndex, 0)
                     backgroundSheet.modelIndex = index
                     backgroundSheet.showClock = view.model.data(index, ThemesModel.ShowClockRole)
+                    backgroundSheet.blurBackground = view.model.data(index, ThemesModel.BlurBackgroundRole)
                     backgroundSheet.imagePath = Qt.binding(() => model.currentBackground)
                     backgroundSheet.open()
                 }
@@ -166,6 +167,7 @@ KCM.GridViewKCM {
         property var modelIndex
         property string imagePath
         property bool showClock
+        property bool blurBackground

         title: i18nc("@title:window", "Change Background")

@@ -257,10 +259,20 @@ KCM.GridViewKCM {
             }
         }

-        footerLeadingComponent: QQC2.CheckBox {
-            text: i18nc("@option:check", "Show clock")
-            checked: backgroundSheet.showClock
-            onToggled: view.model.setData(backgroundSheet.modelIndex, checked, ThemesModel.ShowClockRole)
+        footerLeadingComponent: RowLayout {
+            spacing: Kirigami.Units.largeSpacing
+
+            QQC2.CheckBox {
+                text: i18nc("@option:check", "Show clock")
+                checked: backgroundSheet.showClock
+                onToggled: view.model.setData(backgroundSheet.modelIndex, checked, ThemesModel.ShowClockRole)
+            }
+
+            QQC2.CheckBox {
+                text: i18nc("@option:check", "Blur behind login prompt")
+                checked: backgroundSheet.blurBackground
+                onToggled: view.model.setData(backgroundSheet.modelIndex, checked, ThemesModel.BlurBackgroundRole)
+            }
         }

         customFooterActions: [
-- 
